migrations.018_enforce_finalized_invoice_lock.sql:
-- Migration: Enforce finalized invoice immutability
-- Created: 2026-03-26
-- Description: Prevents accidental edits/deletes to finalized invoices and their line items

CREATE OR REPLACE FUNCTION public.prevent_finalized_invoice_mutation()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.status = 'finalized' THEN
    RAISE EXCEPTION 'Finalized invoices cannot be updated. Use credit/debit note flow for corrections.';
  END IF;

  IF TG_OP = 'DELETE' AND OLD.status = 'finalized' THEN
    RAISE EXCEPTION 'Finalized invoices cannot be deleted.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_prevent_finalized_invoice_mutation ON public.invoices;
CREATE TRIGGER trg_prevent_finalized_invoice_mutation
  BEFORE UPDATE OR DELETE ON public.invoices
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_finalized_invoice_mutation();

CREATE OR REPLACE FUNCTION public.prevent_finalized_invoice_item_mutation()
RETURNS TRIGGER AS $$
DECLARE
  parent_status VARCHAR(20);
BEGIN
  SELECT status INTO parent_status
  FROM public.invoices
  WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);

  IF parent_status = 'finalized' THEN
    RAISE EXCEPTION 'Items of finalized invoices cannot be modified.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_prevent_finalized_invoice_item_mutation ON public.invoice_items;
CREATE TRIGGER trg_prevent_finalized_invoice_item_mutation
  BEFORE UPDATE OR DELETE ON public.invoice_items
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_finalized_invoice_item_mutation();
